ENGINE=''
READINESS=''
"""Signed original-USB entry; uploaded scripts are never used by Poly / View."""
import base64
import contextlib
import fcntl
import io
import json
import os
from pathlib import Path
import re
import signal
import stat
import subprocess
import sys
import tempfile
import time
import traceback
import uuid
import zipfile


class Log:
    """Try independent sinks; report loss without interrupting transaction recovery."""
    def __init__(self, paths):
        self.streams=[];self.errors=[];self.warned=False
        for candidate in paths:
            try:
                path=candidate() if callable(candidate) else candidate
                fd=os.open(str(path),os.O_WRONLY|os.O_CREAT|os.O_APPEND|os.O_NOFOLLOW,0o600)
                info=os.fstat(fd)
                if not stat.S_ISREG(info.st_mode) or info.st_nlink!=1:
                    os.close(fd);raise ValueError('Unsafe installation log')
                self.streams.append(os.fdopen(fd,'w',buffering=1))
            except (OSError,ValueError) as error:self.errors.append(str(error))
        self.require_durable()
        if self.errors:self.write('Installation log sink unavailable: '+'; '.join(self.errors)+'\n')
    def require_durable(self):
        if not self.streams:raise ValueError('Cannot retain an installation log: '+'; '.join(self.errors))
    def failed(self,stream,error):
        self.errors.append(str(error));self.streams.remove(stream)
        try:stream.close()
        except OSError:pass
        if not self.streams and not self.warned:
            self.warned=True
            # fd2 is the original systemd console/journal, not this Python object.
            # Never turn a logging failure into an exception during rollback.
            try:os.write(2,('DURABLE INSTALLATION LOG LOST; transaction recovery continues: '+str(error)+'\n').encode())
            except OSError:pass
    def write(self,text):
        for stream in tuple(self.streams):
            try:stream.write(text);stream.flush();os.fsync(stream.fileno())
            except OSError as error:self.failed(stream,error)
        return len(text) if self.streams else 0
    def flush(self):
        for stream in tuple(self.streams):
            try:stream.flush();os.fsync(stream.fileno())
            except OSError as error:self.failed(stream,error)


def emit(stage):
    print(time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())+
          '  [boot +%.3fs] '%time.monotonic()+stage,flush=True)


def startup_log(service):
    """Retain the entry phase on protected SD even if USB disappears."""
    parent=Path('/mnt/community-lab')
    service.engine.Device.protected(parent.parent)
    parent.mkdir(mode=0o700,exist_ok=True)
    service.engine.Device.protected(parent)
    root=parent/'poly-view-usb-startup'
    root.mkdir(mode=0o700,exist_ok=True)
    service.engine.Device.protected(root)
    boot=Path('/proc/sys/kernel/random/boot_id').read_text().strip()
    if not re.fullmatch(r'[A-Za-z0-9_-]{1,64}',boot):raise ValueError('Invalid boot identifier')
    return root/('entry-'+boot+'-'+str(os.getpid())+'.log')


def wait_for_repair(service,tr,usb,timeout=90):
    from system_readiness import wait
    return wait(timeout=timeout,allow_absent=True,allow_legacy_upgrade=True,allow_initial_staging=True,emit=emit)


@contextlib.contextmanager
def verification_budget(seconds=90):
    def expired(signum,frame):
        raise TimeoutError('USB verification exceeded90seconds. No app files changed; inspect the saved startup log.')
    previous=signal.signal(signal.SIGALRM,expired)
    old_timer=signal.alarm(seconds)
    try:yield
    finally:
        signal.alarm(0);signal.signal(signal.SIGALRM,previous)
        if old_timer:signal.alarm(old_timer)


def worker(folder,release,service,tr):
    service.engine.Device.protected(folder)
    sys.stdout=sys.stderr=Log([folder/'install.log',Path('/usb_flash/POLY-VIEW-INSTALL.log')])
    emit('Independent USB worker entered. Verifying the staged signed release and shared support.')
    raw=service.protected(folder/'release.zip',release.LIMIT)
    request=json.loads(service.protected(folder/'request.json'))
    info,content,_=release.read(raw)
    import system_support
    from publisher_release import PublisherPolicy
    repair=system_support.validate_runtime(info,content,PublisherPolicy())
    if (folder.name!=request['id'] or release.sha(raw)!=request['key'] or
            tr.digest(service.protected(folder/'install.py'))!=request['entry_sha256']):
        raise ValueError('The staged USB release changed')
    emit('Verified '+info['name']+' '+info['version']+'. Independent USB worker started.')
    emit('Waiting for normal startup to finish before measuring saved presets.')
    # This is independent of debug_script.service. A first-boot USB invocation
    # must return so the vendor startup/mount service can finish normally.
    deadline=time.monotonic()+150
    while True:
        boot_state=subprocess.run(['/bin/systemctl','is-system-running'],capture_output=True,text=True,timeout=5)
        if boot_state.stdout.strip() in ('running','degraded'):break
        if time.monotonic()>=deadline:raise ValueError('System startup did not finish; no firmware writes requested')
        time.sleep(1)
    if request.get('operation')!='rollback':
        # All app baseline admission uses SD files, never the faulty NOR bank.
        # Refuse an incompatible app before staging even shared support files.
        release.select(info,content,Path('/overlay/lower'))
        emit('Checking Flash Repair before reading saved presets.')
        bridge=system_support.bridge_for_release(raw,PublisherPolicy())
        result=system_support.usb_prepare_repair(repair,PublisherPolicy(),request['source_release_sha256'],bridge=bridge,continuation_marker=('usb-platform '+request['id']+'\n').encode(),allow_legacy_upgrade=True)
        if result['reboot_requested']:
            tr.atomic(folder/'result.json',tr.canonical(result))
            emit('STAGE1/2: Flash Repair verified. Restarting automatically to activate it before presets are read.')
            emit('Leave the USB inserted. The same installer resumes Network Connection automatically after this restart.')
            return result
        emit('STAGE2/2: Flash Repair is active and confirmed. Continuing guarded Network Connection installation.')
    else:
        from system_readiness import wait
        wait()  # Explicit app rollback also reads NOR; never bypass failed support.
    sys.stdout.require_durable()
    last=None;stable=0
    probe=service.engine.Device.__new__(service.engine.Device);probe.root=Path('/')
    deadline=time.monotonic()+30
    while stable<2:
        try:current=probe.presets()
        except (OSError,ValueError):current=None
        stable=stable+1 if current is not None and current==last else 0
        last=current
        if time.monotonic()>=deadline:raise ValueError('Saved presets are still changing during startup; no firmware writes requested')
        time.sleep(.5)
    emit('Startup finished. Verifying device, files, saved data and recovery backup.')
    operation=service.engine.operate
    def observed(device,action,manifest,payload,approval,token,checkpoint=lambda *a:None):
        for method,label in [('pause','Pausing the touchscreen and audio consumers'),('writable','Opening the guarded write transaction'),('readonly','Verifying and closing the firmware filesystem'),('reboot','Installation verified. Restarting automatically')]:
            previous=getattr(device,method)
            def wrapped(*args,_previous=previous,_label=label,**kwargs):
                emit(_label);return _previous(*args,**kwargs)
            setattr(device,method,wrapped)
        count=[0];total=len(payload);last_percent=[-1]
        def progress(stage,name):
            checkpoint(stage,name)
            if stage=='after':
                count[0]+=1;percent=round(100*count[0]/max(total,1))
                if percent//10!=last_percent[0]//10:
                    emit('Files verified: '+str(count[0])+'/'+str(total)+' ('+str(percent)+'%)');last_percent[0]=percent
        return operation(device,action,manifest,payload,approval,token,progress)
    service.engine.operate=observed
    result=service.run_usb_rollback(raw,request) if request.get('operation')=='rollback' else service.run_install(raw,request)
    tr.atomic(folder/'result.json',tr.canonical(result))
    emit(json.dumps(result,sort_keys=True))
    if not result.get('device_written') and not result.get('reboot_requested'):
        service.MARKER.unlink(missing_ok=True)
    return result


def launch(release,service,tr):
    sys.stdout=sys.stderr=Log([lambda: startup_log(service),Path('/usb_flash/POLY-VIEW-INSTALL.log')])
    emit('Network Connection USB launcher started. No internet is required.')
    emit('Available persistent installation log sinks: '+str(len(sys.stdout.streams)))
    usb=Path(__file__).resolve().parent.parent
    wait_for_repair(service,tr,usb)
    with verification_budget():
        emit('Reading the signed publisher inventory.')
        proof=json.loads(tr.regular(usb/'publisher.json',128*1024))
        if not isinstance(proof.get('files'),dict) or not 1<=len(proof['files'])<=510:
            raise ValueError('Invalid bounded release inventory')
        names=[*proof['files'],'publisher.json','publisher.sig'];files={};total=0
        for index,name in enumerate(names,1):
            if index==1 or index%16==0:
                emit('Reading USB files: '+str(index)+'/'+str(len(names))+'; '+name)
            files[name]=tr.regular(tr.safe(usb,name),release.LIMIT)
            total+=len(files[name])
            if total>32*1024*1024:raise ValueError('The unpacked USB release exceeds its limit')
        emit('Rebuilding the signed release from the USB files.')
        output=io.BytesIO()
        with zipfile.ZipFile(output,'w',zipfile.ZIP_DEFLATED) as archive:
            for name,content in files.items():archive.writestr(name,content)
        raw=output.getvalue()
        emit('Verifying publisher signature, platform compatibility and all payload hashes.')
        info,verified,_=release.read(raw)
    sys.stdout.require_durable()
    source=tr.digest(tr.canonical(proof))
    emit('Publisher signature and complete release inventory verified: '+info['version'])
    service.resume_pending()
    rollback_flag=usb/'ROLLBACK-POLY-VIEW.txt';rollback=False
    if rollback_flag.exists():
        if tr.regular(rollback_flag,256).decode().strip()!=info['id']+'\n'+info['version']:
            raise ValueError('Rollback instruction does not identify this exact release')
        rollback=True;os.replace(rollback_flag,usb/'ROLLBACK-POLY-VIEW.used')
        emit('Explicit USB rollback requested for this exact release.')
    if not rollback and not service.automatic_allowed(source,info['id']):
        emit('This release was already processed or recovery is pending. No repeat installation.');return
    lower=Path('/overlay/lower')
    if not rollback and any(all(tr.file_hash(tr.safe(lower,row['path']))==row['sha256'] for row in profile['files']) and
           all(tr.file_hash(tr.safe(lower,name))==value for name,value in profile['guards'].items()) for profile in info['profiles']):
        emit('This release is already installed. No restart is needed.')
        service.mark_processed(dict(source_release_sha256=source,platform_id=info['id'],version=info['version'],status='verified'));return
    # Stage the signed bytes, not a mutable USB path, before the vendor service
    # returns. Existing protected recovery history is retained.
    service.DATA.parent.mkdir(mode=0o755,parents=True,exist_ok=True)
    service.engine.Device.protected(service.DATA.parent)
    service.DATA.mkdir(mode=0o700,exist_ok=True);service.engine.Device.protected(service.DATA)
    inbox=service.DATA/'usb-inbox';inbox.mkdir(mode=0o700,exist_ok=True);service.engine.Device.protected(inbox)
    token=uuid.uuid4().hex;folder=inbox/token;folder.mkdir(mode=0o700)
    request=dict(id=token,boot=Path('/proc/sys/kernel/random/boot_id').read_text().strip(),key=release.sha(raw),saved_patch=True,
                 source_release_sha256=source,entry_sha256=tr.digest(verified['poly-view/install.py']),operation='rollback' if rollback else 'install')
    tr.atomic(folder/'install.py',verified['poly-view/install.py']);tr.atomic(folder/'release.zip',raw);tr.atomic(folder/'request.json',tr.canonical(request))
    marker_value=('usb-platform '+token+'\n').encode()
    fd=os.open(service.MARKER,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,'wb') as stream:stream.write(marker_value);stream.flush();os.fsync(stream.fileno())
    unit='poly-view-usb-'+token
    args=['/usr/bin/systemd-run','--quiet','--no-block','--unit='+unit,'--property=Type=simple',
          '--property=TimeoutStartSec=30','--property=RuntimeMaxSec=1200','--property=TimeoutStopSec=90','--property=Restart=no','--property=LimitCORE=0',
          '--property=StandardOutput=append:'+str(folder/'install.log'),'--property=StandardError=inherit',
          '/usr/bin/python3','-I','-B',str(folder/'install.py'),'--worker',str(folder)]
    try:subprocess.run(args,check=True,capture_output=True,text=True,timeout=15)
    except Exception:
        if tr.regular(service.MARKER,512)==marker_value:service.MARKER.unlink()
        raise
    emit('Handed installation to '+unit+'. The startup launcher is finished.')
    emit('Keep power on. Hector will restart automatically after the verified installation.')
    os.sync()


def main():
    if sys.version_info<(3,9):raise ValueError('Python 3.9 or newer is required; no files changed')
    if os.geteuid()!=0:raise ValueError('Run through the original USB startup process')
    with tempfile.TemporaryDirectory(prefix='poly-view-usb-') as temporary:
        temporary=Path(temporary)
        with zipfile.ZipFile(io.BytesIO(base64.b64decode(ENGINE))) as archive:
            for name in archive.namelist():
                if '/' in name or name.startswith('.'):raise ValueError('Invalid embedded installer')
                (temporary/name).write_bytes(archive.read(name))
        (temporary/'system_readiness.py').write_bytes(base64.b64decode(READINESS,validate=True))
        sys.path.insert(0,str(temporary))
        import platform_release as release,platform_service as service,platform_transaction as tr
        if len(sys.argv)==3 and sys.argv[1]=='--worker':worker(Path(sys.argv[2]),release,service,tr)
        elif len(sys.argv)==1:launch(release,service,tr)
        else:raise ValueError('Unknown USB operation')


if __name__=='__main__':
    try:main()
    except Exception:
        traceback.print_exc();sys.stdout.flush();raise SystemExit(1)
